#include "mmx_boss_rush_foreign.h"
#include "mmx_boss_rush.h"
#include "mmx_cart_extension.h"
#include "mmx_boss_rush_audio.h"
#include "mmx_boss_rush_foreign_art.h"
#include <stdio.h>
#include <string.h>

/* Relocation descriptors generated by tools/relocate_boss.py. They hold only
 * addresses and the original operand values used to verify the source ROM;
 * code and data are copied from the user's ROM here, in memory. */
typedef struct MmxRelocBank {uint8_t source,dest;} MmxRelocBank;
typedef struct MmxRelocCopy {uint32_t source,dest;uint16_t size;} MmxRelocCopy;
typedef struct MmxRelocBlob {uint32_t at;uint16_t offset,size;} MmxRelocBlob;
typedef struct MmxRelocPatch {uint32_t at;uint8_t size;uint32_t expected,value;} MmxRelocPatch;
typedef struct MmxRelocChild {uint8_t kind;uint32_t controller;} MmxRelocChild;
/* See MmxBossRushForeignArtSetEffectFilter. */
typedef struct MmxRelocEffectFilter {uint8_t kind,set,first,last;} MmxRelocEffectFilter;
#include "mmx_boss_rush_x3_rhino.inc"
#include "mmx_boss_rush_x2_sponge.inc"
#ifndef MMX_SPONGE_ENTRY_Y
#define MMX_SPONGE_ENTRY_Y 0x20
#endif

typedef struct MmxRelocBoss {
  const char *name;
  unsigned game,roster_id;
  uint32_t body;
  uint8_t fighting,dying;
  const MmxRelocBank *banks;size_t bank_count;
  const MmxRelocCopy *copies;size_t copy_count;
  const uint8_t *code;
  const MmxRelocBlob *blobs;size_t blob_count;
  const MmxRelocPatch *patches;size_t patch_count;
  const MmxRelocChild *children;size_t child_count;
  unsigned sound_bank;uint32_t sfx,sfx_pan;
  const uint8_t *effects;size_t effect_count;
  const MmxBossRushWeakness *weaknesses;size_t weakness_count;
  uint32_t palette_rotate,palette_fade; /* relocated helpers Rush runs privately */
  const uint32_t *midline;size_t midline_count; /* room-half tests (LDA $05) */
  const MmxBossRushSpawnGuard *spawns;size_t spawn_count;
  const MmxBossRushChildGuard *child_guards;size_t child_guard_count;
  const MmxRelocChild *effect_children;size_t effect_child_count; /* $1928 list */
  uint32_t scratch;unsigned scratch_size; /* work RAM body and children share */
  uint32_t saber_kill;uint8_t saber_value; /* death test that reads the killing class */
  const MmxBossRushRoomRead *room_reads;size_t room_read_count;
  uint8_t death_field,death_value,death_frames; /* own death sequence */
  const MmxBossRushPoke *pokes;size_t poke_count;
  const MmxRelocEffectFilter *effect_filters;size_t effect_filter_count;
} MmxRelocBoss;
#define COUNT(a) (sizeof(a)/sizeof(*(a)))
/* X1 shot classes: weapon n fires class $0F-n (Homing Torpedo $0E, Fire
 * Wave $0B, Shotgun Ice $07); charged +9. */
enum { X1_ICE=0x07, X1_FIRE=0x0b, X1_TORPEDO=0x0e, CHARGED=9 };
/* Rhino runs on Kuwanger's X1 row, whose weakness column is Homing Torpedo's.
 * His original X3 weakness, Acid Burst, takes that column and reports the
 * Torpedo reaction his relocated flinch test looks for. Homing Torpedo
 * itself is moved to an ordinary column (Ice) so it is not a weakness.
 * Extra X1/X2 weaknesses are assigned once all 24 bosses exist. */
static const MmxBossRushWeakness k_rhino_weaknesses[]={
  {2,1,{X1_TORPEDO,X1_TORPEDO+CHARGED},{X1_TORPEDO,X1_TORPEDO+CHARGED}}, /* X3 Acid Burst */
  {0,1,{X1_ICE,X1_ICE+CHARGED},{X1_ICE,X1_ICE+CHARGED}},                 /* X1 Homing Torpedo */
};
/* Which half of the room he is in: turning away from a wall ($3F:EB30),
 * allowing the stop-and-fire charge only toward the center ($EB50), and
 * stopping that charge, which skips the wall check, at the midline
 * ($E8C1/$E8C7). */
static const uint32_t k_rhino_midline[]={0x3fe8c1,0x3fe8c7,0x3feb30,0x3feb50};
/* $3D counts his live volley and spread drills. The volley sets it before
 * its spawns ($3F:EC08 after each allocation); the spread stores 3 after its
 * loop, which stops with $3A drills unspawned ($EA85). The pin carrier
 * ($EBE7) is not counted. */
static const MmxBossRushSpawnGuard k_rhino_spawns[]={{0x3fec08,0x3d,0},{0x3fea85,0x3d,0x3a}};
/* His pin carrier (drill class $26, variant $3C = 2) catches the player in
 * X3's state $12. The pin ($3F:EB78) locks a caught player: require the
 * carrier, or any hit during his recoil would lock the player. The drill
 * charge spawns a carrier on every frame it overlaps the player ($E994);
 * X3's caught player stops overlapping, X1's does not, so spawn one. */
static const MmxBossRushChildGuard k_rhino_child_guards[]={{0x3feb78,0x26,0x3c,2},{0x3fe994,0x26,0x3c,2}};
/* Wire Sponge runs on Chill Penguin's X1 row, whose weakness column is
 * Fire Wave's class $0B/$14: the same classes X2's Sonic Slicer has, so his
 * relocated flinch and split tests need no change. Fire Wave itself moves to
 * an ordinary column (Ice). */
static const MmxBossRushWeakness k_sponge_weaknesses[]={
  {1,5,{X1_FIRE,X1_FIRE+CHARGED},{X1_FIRE,X1_FIRE+CHARGED}}, /* X2 Sonic Slicer */
  {0,4,{X1_ICE,X1_ICE+CHARGED},{X1_ICE,X1_ICE+CHARGED}},     /* X1 Fire Wave */
};
/* His entrance drops him from the top of X2's 256-pixel room ($04:9ADB),
 * which is open sky there; the Rush arena has a ceiling. Start below it, so
 * the fall lasts long enough for his vine to finish lowering (its segment
 * count $7F:CD90 counts down every 6 frames while he falls). */
static const MmxBossRushRoomRead k_sponge_rooms[]={{0xb59adb,1,MMX_SPONGE_ENTRY_Y}};
/* While he falls he lowers his 11 whip segments, one every 6 frames
 * ($7F:CD90 counts them down); his vine waits for 0 before it climbs to
 * him. X2 drops him from far above, so all are down before he lands. Rush's
 * shorter fall (62-66 frames) could land him with one left: the vine then
 * waited forever and he never left his entrance. Landing ($04:9BD5) lowers
 * the rest; the vine must not arrive sooner, while his landing pose plays. */
static const MmxBossRushPoke k_sponge_pokes[]={{0xb59bd5,0x7fcd90,0}};
/* His whip segments ($1F, variants $00-$0E) and split halves ($2B, variants
 * $52/$53) use his set $3E. X1's terrain helper spawns X1 rubble ($2B) in his
 * seat when his vine hits the ceiling; X2 shows none there. */
static const MmxRelocEffectFilter k_sponge_effect_filters[]={{0x1f,0x3e,0x00,0x0e},{0x2b,0x3e,0x52,0x53}};
static const MmxRelocBoss kBosses[]={
  {"TUNNEL RHINO",3,k_rhino_roster_id,k_rhino_body,2,4,
   k_rhino_banks,COUNT(k_rhino_banks),k_rhino_copies,COUNT(k_rhino_copies),
   k_rhino_shim_code,k_rhino_blobs,COUNT(k_rhino_blobs),
   k_rhino_patches,COUNT(k_rhino_patches),k_rhino_children,COUNT(k_rhino_children),
   k_rhino_sound_bank,k_rhino_sfx,k_rhino_sfx_pan,k_rhino_effects,COUNT(k_rhino_effects),
   k_rhino_weaknesses,COUNT(k_rhino_weaknesses),
   /* X3 $13:F7D6 rotates OBJ colors 1-15; $13:F7FC fades them back. */
   0x33f7d6,0x33f7fc,k_rhino_midline,COUNT(k_rhino_midline),
   k_rhino_spawns,COUNT(k_rhino_spawns),k_rhino_child_guards,COUNT(k_rhino_child_guards),
   k_rhino_effect_children,k_rhino_effect_child_count,0,0,0,0,NULL,0,0,0,0,NULL,0,NULL,0},
  {"WIRE SPONGE",2,k_sponge_roster_id,k_sponge_body,2,4,
   k_sponge_banks,COUNT(k_sponge_banks),k_sponge_copies,COUNT(k_sponge_copies),
   k_sponge_shim_code,k_sponge_blobs,COUNT(k_sponge_blobs),
   k_sponge_patches,COUNT(k_sponge_patches),k_sponge_children,COUNT(k_sponge_children),
   k_sponge_sound_bank,k_sponge_sfx,k_sponge_sfx_pan,k_sponge_effects,COUNT(k_sponge_effects),
   k_sponge_weaknesses,COUNT(k_sponge_weaknesses),0,0,NULL,0,NULL,0,NULL,0,
   k_sponge_effect_children,k_sponge_effect_child_count,
   /* $7F:CD90-$7F:CD96: state his body, whip and bolts share. */
   0x7fcd90,7,
   /* $04:A70C LDA $3D: his last hit's class; $0B splits him in two. */
   0xb5a70c,X1_FIRE,k_sponge_rooms,COUNT(k_sponge_rooms),
   /* Death path $3B = 6 splits him in two: fall, land, 30 frames, the halves
   * part, 60 frames, then his explosion. */
   0x3b,6,180,k_sponge_pokes,COUNT(k_sponge_pokes),k_sponge_effect_filters,COUNT(k_sponge_effect_filters)},
};
/* Zero/sink area for X3-only globals: reads see zero, writes hit ROM. */
enum { ZERO_AREA=0x86fe40, ZERO_SIZE=0x100 };

static bool source(const uint8_t *rom,size_t size,uint32_t address,size_t n,const uint8_t **out) {
  if((address&0xffff)<0x8000) return false;
  size_t at=((size_t)((address>>16)&0x7f)<<15)|(address&0x7fff);
  if(at>size || n>size-at) return false;
  *out=rom+at;return true;
}
static bool build(const MmxRelocBoss *boss,const uint8_t *rom,size_t size,char *error,size_t cap) {
  for(size_t i=0;i<boss->bank_count;++i) {
    const uint8_t *bytes;
    if(!source(rom,size,(uint32_t)boss->banks[i].source<<16|0x8000,0x8000,&bytes) ||
        !MmxCartExtensionWrite((uint32_t)boss->banks[i].dest<<16|0x8000,bytes,0x8000)) {
      snprintf(error,cap,"%s: cannot copy bank $%02X",boss->name,boss->banks[i].source);return false;
    }
  }
  /* Shims first: copies fill the class-init shim's immediates. */
  for(size_t i=0;i<boss->blob_count;++i) {
    const MmxRelocBlob *b=&boss->blobs[i];
    if(!MmxCartExtensionWrite(b->at,boss->code+b->offset,b->size)) {
      snprintf(error,cap,"%s: cannot place shim $%06X",boss->name,b->at);return false;
    }
  }
  for(size_t i=0;i<boss->copy_count;++i) {
    const uint8_t *bytes;const MmxRelocCopy *c=&boss->copies[i];
    if(!source(rom,size,c->source,c->size,&bytes) || !MmxCartExtensionWrite(c->dest,bytes,c->size)) {
      snprintf(error,cap,"%s: cannot copy $%06X",boss->name,c->source);return false;
    }
  }
  static const uint8_t zero[ZERO_SIZE];
  if(!MmxCartExtensionWrite(ZERO_AREA,zero,sizeof(zero))) {
    snprintf(error,cap,"%s: cannot reserve the zero area",boss->name);return false;
  }
  for(size_t i=0;i<boss->patch_count;++i) {
    const MmxRelocPatch *p=&boss->patches[i];
    uint8_t now[3]={0},value[3]={(uint8_t)p->value,(uint8_t)(p->value>>8),(uint8_t)(p->value>>16)};
    uint32_t found=0;
    if(p->size<1 || p->size>3 || !MmxCartExtensionRead(p->at,now,p->size)) {
      snprintf(error,cap,"%s: invalid patch $%06X",boss->name,p->at);return false;
    }
    for(unsigned k=0;k<p->size;++k) found|=(uint32_t)now[k]<<(8*k);
    /* The source ROM must hold the traced operand before it is rewritten. */
    if(found!=p->expected || !MmxCartExtensionWrite(p->at,value,p->size)) {
      snprintf(error,cap,"%s: unexpected operand at $%06X",boss->name,p->at);return false;
    }
  }
  if(!MmxBossRushForeignSetController(boss->roster_id,boss->body) ||
      !MmxBossRushForeignSetStates(boss->roster_id,boss->fighting,boss->dying)) {
    snprintf(error,cap,"%s: cannot register its body",boss->name);return false;
  }
  for(size_t i=0;i<boss->child_count;++i)
    if(!MmxBossRushForeignSetChild(boss->roster_id,boss->children[i].kind,boss->children[i].controller)) {
      snprintf(error,cap,"%s: cannot register projectile $%02X",boss->name,boss->children[i].kind);return false;
    }
  for(size_t i=0;i<boss->effect_child_count;++i)
    if(!MmxBossRushForeignSetEffectChild(boss->roster_id,boss->effect_children[i].kind,
        boss->effect_children[i].controller)) {
      snprintf(error,cap,"%s: cannot register effect $%02X",boss->name,boss->effect_children[i].kind);return false;
    }
  for(size_t i=0;i<boss->effect_filter_count;++i) {
    const MmxRelocEffectFilter *f=&boss->effect_filters[i];
    MmxBossRushForeignArtSetEffectFilter(boss->roster_id,f->kind,f->set,f->first,f->last);
  }
  if(!MmxBossRushForeignSetScratch(boss->roster_id,boss->scratch,boss->scratch_size) ||
      (boss->saber_kill && !MmxBossRushForeignSetSaberKill(boss->roster_id,boss->saber_kill,boss->saber_value))) {
    snprintf(error,cap,"%s: cannot register its shared state",boss->name);return false;
  }
  /* Its X3 sound calls are hooked shims; render those effects from its own
   * driver and sound bank. A failed cache leaves the boss silent. */
  if(!MmxBossRushForeignSetWeaknesses(boss->roster_id,boss->weaknesses,(unsigned)boss->weakness_count)) {
    snprintf(error,cap,"%s: cannot register its weaknesses",boss->name);return false;
  }
  MmxBossRushForeignAddSoundShims(boss->sfx,boss->sfx_pan);
  MmxBossRushForeignAddPaletteHooks(boss->palette_rotate,boss->palette_fade);
  MmxBossRushForeignAddMidlineReads(boss->midline,(unsigned)boss->midline_count);
  MmxBossRushForeignAddSpawnGuards(boss->spawns,(unsigned)boss->spawn_count);
  MmxBossRushForeignAddChildGuards(boss->child_guards,(unsigned)boss->child_guard_count);
  MmxBossRushForeignAddRoomReads(boss->room_reads,(unsigned)boss->room_read_count);
  MmxBossRushForeignAddPokes(boss->pokes,(unsigned)boss->poke_count);
  if(boss->death_frames &&
      !MmxBossRushForeignSetOwnDeath(boss->roster_id,boss->death_field,boss->death_value,boss->death_frames)) {
    snprintf(error,cap,"%s: cannot register its death sequence",boss->name);return false;
  }
  MmxBossRushAudioPrepareForeign(boss->roster_id,rom,size,boss->sound_bank,boss->effects,(unsigned)boss->effect_count);
  return true;
}
bool MmxBossRushForeignBuild(char *error,size_t cap) {
  for(size_t i=0;i<COUNT(kBosses);++i) MmxBossRushForeignSetController(kBosses[i].roster_id,0);
  MmxBossRushForeignResetHooks();
  MmxCartExtensionClear();
  if(!MmxCartPatchAvailable()) {
    snprintf(error,cap,"The loaded Mega Man X image cannot host relocated bosses.");return false;
  }
  for(size_t i=0;i<COUNT(kBosses);++i) {
    size_t size=0;const uint8_t *rom=MmxBossRushForeignRom(kBosses[i].game,&size);
    if(!rom) {MmxBossRushAudioPrepareForeign(kBosses[i].roster_id,NULL,0,0,NULL,0);continue;}
    if(!build(&kBosses[i],rom,size,error,cap)) {
      MmxBossRushForeignSetController(kBosses[i].roster_id,0);MmxCartExtensionClear();
      return false;
    }
  }
  if(error && cap) error[0]=0;
  return true;
}
